2	/**
3	 * Slide-in: a pinned CTA that arrives halfway down an article, entering from
4	 * the bottom edge. Never darkens or locks the page, which is the whole point:
5	 * a blocking lightbox converts better and costs a mobile-interstitial penalty
6	 * plus the first-party tone. See HISTORY.md.
7	 *
8	 * Only blog posts and glossary entries use it, and neither imports the sticky
9	 * bar, which is how "one pinned surface per page" is held.
10	 *
11	 * The two buttons are answers to the heading's question, and both go to the
12	 * quiz cover. They carry nothing into the quiz (the prefill idea is shelved:
13	 * see HISTORY.md); they differ only by utm_content, so the numbers say which
14	 * framing pulled people in.
15	 */
16	import {
17	  CTA_DEFAULTS,
18	  CTA_PRIMARY,
19	  CTA_VARIANT,
20	  CTA_VARIANT_IDS,
21	  SLIDE_IN_CONFIG,
22	  type Attribution,
23	} from '@/constants/cta';
24	import { addUTMParams } from '@/utils/tracking';
25	
26	interface Props {
27	  attribution: Attribution;
28	}
29	
30	const { attribution } = Astro.props;
31	
32	const hrefs = {
33	  primary: {
34	    unsure: addUTMParams(
35	      CTA_PRIMARY.buttonLink,
36	      attribution,
37	      'slide-in',
38	      'not-sure'
39	    ),
40	    confident: addUTMParams(
41	      CTA_PRIMARY.buttonLink,
42	      attribution,
43	      'slide-in',
44	      'i-think-i-know'
45	    ),
46	  },
47	  variant: {
48	    unsure: CTA_VARIANT
49	      ? addUTMParams(CTA_VARIANT.buttonLink, attribution, 'slide-in', 'not-sure')
50	      : '',
51	    confident: CTA_VARIANT
52	      ? addUTMParams(
53	          CTA_VARIANT.buttonLink,
54	          attribution,
55	          'slide-in',
56	          'i-think-i-know'
57	        )
58	      : '',
59	  },
60	};
61	
62	const panelClass =
63	  'fixed inset-x-0 bottom-0 z-40 hidden translate-y-full border-t-2 border-blue-300 bg-white shadow-2xl transition-transform duration-300 ease-out sm:inset-x-auto sm:right-6 sm:bottom-6 sm:max-w-sm sm:rounded-xl sm:border-2';
64	const buttonClass =
65	  'inline-flex h-10 flex-1 items-center justify-center rounded-md px-4 text-sm font-semibold transition-colors focus:ring-2 focus:ring-blue-600 focus:ring-offset-2 focus:outline-none';
66	---
67	
68	<aside
69	  class={panelClass}
70	  data-cta-slide-in
71	  data-attribution={attribution}
72	  aria-label="Quiz invitation"
73	>
74	  <button
75	    type="button"
76	    class="absolute top-2 right-2 flex size-9 items-center justify-center rounded-md text-2xl/none text-gray-500 transition-colors hover:bg-gray-100 hover:text-gray-900 focus:ring-2 focus:ring-blue-600 focus:outline-none"
77	    data-cta-dismiss
78	    aria-label={SLIDE_IN_CONFIG.dismissLabel}
79	  >
80	    <span aria-hidden="true">&times;</span>
81	  </button>
82	
83	  <!-- Primary variant -->
84	  <div class="hidden flex-col gap-4 p-5 pr-12" data-variant="primary">
85	    <div class="flex flex-col gap-1">
86	      <p class="text-lg/6 font-bold text-blue-900">
87	        {CTA_PRIMARY.slideInHeading}
88	      </p>
89	      <p class="text-sm text-gray-600">{CTA_PRIMARY.slideInBody}</p>
90	    </div>
91	    <div class="flex gap-3">
92	      <a
93	        href={hrefs.primary.unsure}
94	        class:list={[buttonClass, 'bg-blue-600 text-white hover:bg-blue-700']}
95	        data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
96	        data-ph-capture-attribute-cta-surface="slide-in"
97	        data-ph-capture-attribute-cta-answer="not-sure"
98	        data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
99	      >
100	        {CTA_PRIMARY.slideInButtonPrimaryText}
101	      </a>
102	      <a
103	        href={hrefs.primary.confident}
104	        class:list={[
105	          buttonClass,
106	          'border-2 border-blue-600 text-blue-700 hover:bg-blue-50',
107	        ]}
108	        data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
109	        data-ph-capture-attribute-cta-surface="slide-in"
110	        data-ph-capture-attribute-cta-answer="i-think-i-know"
111	        data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
112	      >
113	        {CTA_PRIMARY.slideInButtonSecondaryText}
114	      </a>
115	    </div>
116	  </div>
117	
118	  {/* Test variant: rendered only when CTA_VARIANT is populated in cta.ts */}
119	  {
120	    CTA_VARIANT && (
121	      <div class="hidden flex-col gap-4 p-5 pr-12" data-variant="variant">
122	        <div class="flex flex-col gap-1">
123	          <p class="text-lg/6 font-bold text-blue-900">
124	            {CTA_VARIANT.slideInHeading}
125	          </p>
126	          <p class="text-sm text-gray-600">{CTA_VARIANT.slideInBody}</p>
127	        </div>
128	        <div class="flex gap-3">
129	          <a
130	            href={hrefs.variant.unsure}
131	            class:list={[
132	              buttonClass,
133	              'bg-blue-600 text-white hover:bg-blue-700',
134	            ]}
135	            data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
136	            data-ph-capture-attribute-cta-surface="slide-in"
137	            data-ph-capture-attribute-cta-answer="not-sure"
138	            data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.variant}
139	          >
140	            {CTA_VARIANT.slideInButtonPrimaryText}
141	          </a>
142	          <a
143	            href={hrefs.variant.confident}
144	            class:list={[
145	              buttonClass,
146	              'border-2 border-blue-600 text-blue-700 hover:bg-blue-50',
147	            ]}
148	            data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
149	            data-ph-capture-attribute-cta-surface="slide-in"
150	            data-ph-capture-attribute-cta-answer="i-think-i-know"
151	            data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.variant}
152	          >
153	            {CTA_VARIANT.slideInButtonSecondaryText}
154	          </a>
155	        </div>
156	      </div>
157	    )
158	  }
159	</aside>
160	
161	<script>
162	  import {
163	    AB_TEST_ENABLED,
164	    SLIDE_IN_CONFIG,
165	    type Attribution,
166	  } from '@/constants/cta';
167	  import { shouldShowSlideIn, recordSlideInShown } from '@/utils/storage';
168	  import { captureCtaEvent } from '@/utils/cta-analytics';
169	
170	  const panel = document.querySelector<HTMLElement>('[data-cta-slide-in]');
171	
172	  if (panel) {
173	    const attribution = (panel.dataset.attribution ?? 'blog') as Attribution;
174	
175	    // Pick random variant (or always primary if A/B testing disabled)
176	    const variantId =
177	      AB_TEST_ENABLED && Math.random() >= 0.5 ? 'variant' : 'primary';
178	    const variantEl = panel.querySelector(`[data-variant="${variantId}"]`);
179	    if (variantEl) {
180	      variantEl.classList.remove('hidden');
181	      variantEl.classList.add('flex');
182	    }
183	
184	    const dismiss = () => {
185	      panel.classList.add('translate-y-full');
186	      captureCtaEvent('cta_dismissed', 'slide-in', attribution);
187	    };
188	
189	    panel
190	      .querySelector('[data-cta-dismiss]')
191	      ?.addEventListener('click', dismiss);
192	
193	    const reveal = () => {
194	      panel.classList.remove('hidden');
195	      // The panel starts translated off-screen. Removing `hidden` and clearing
196	      // the transform in the same frame would give the browser nothing to
197	      // animate between, so the slide would not happen at all.
198	      requestAnimationFrame(() => {
199	        panel.classList.remove('translate-y-full');
200	      });
201	      // The suppression clock starts here, on appearance, not on dismissal.
202	      recordSlideInShown();
203	      captureCtaEvent('cta_shown', 'slide-in', attribution);
204	    };
205	
206	    if (shouldShowSlideIn(SLIDE_IN_CONFIG.displayIntervalDays)) {
207	      const onScroll = () => {
208	        const scrollable =
209	          document.documentElement.scrollHeight - window.innerHeight;
210	        // A page shorter than the viewport can never reach any threshold, so
211	        // there is nothing to trigger and no slide-in.
212	        if (scrollable <= 0) return;
213	
214	        if (window.scrollY / scrollable >= SLIDE_IN_CONFIG.scrollTriggerFraction) {
215	          window.removeEventListener('scroll', onScroll);
216	          reveal();
217	        }
218	      };
219	
220	      window.addEventListener('scroll', onScroll, { passive: true });
221	    }
222	  }
223	</script>
