2	/**
3	 * Sticky bar: a full-width pinned CTA at the bottom edge, on screen at every
4	 * scroll position until dismissed.
5	 *
6	 * A page shows the sticky bar OR the slide-in, never both. That rule is held by
7	 * the routes: no page imports both components. Blog posts and glossary entries
8	 * take the slide-in; the index/listing pages and most content pages take this.
9	 *
10	 * All copy comes from src/constants/cta.ts. No copy props, for the same reason
11	 * link-sidebar.astro has none: per-call overrides are how the sidebar's copy
12	 * drifted out of date before it was consolidated.
13	 */
14	import {
15	  CTA_DEFAULTS,
16	  CTA_PRIMARY,
17	  CTA_VARIANT,
18	  CTA_VARIANT_IDS,
19	  STICKY_BAR_CONFIG,
20	  type Attribution,
21	} from '@/constants/cta';
22	import { addUTMParams } from '@/utils/tracking';
23	
24	interface Props {
25	  attribution: Attribution;
26	}
27	
28	const { attribution } = Astro.props;
29	
30	const primaryHref = addUTMParams(
31	  CTA_PRIMARY.buttonLink,
32	  attribution,
33	  'sticky-bar'
34	);
35	const variantHref = CTA_VARIANT
36	  ? addUTMParams(CTA_VARIANT.buttonLink, attribution, 'sticky-bar')
37	  : '';
38	---
39	
40	<div
41	  class="fixed inset-x-0 bottom-0 z-40 hidden border-t-2 border-blue-300 bg-blue-800 text-white shadow-lg"
42	  data-cta-sticky-bar
43	  data-attribution={attribution}
44	>
45	  <div
46	    class="container mx-auto flex items-center justify-center gap-3 px-4 py-3 pr-12 sm:gap-6 sm:pr-14"
47	  >
48	    <!-- Primary variant -->
49	    <div
50	      class="hidden flex-col items-center gap-2 text-center sm:flex-row sm:gap-6"
51	      data-variant="primary"
52	    >
53	      <p class="text-sm/5 font-medium sm:text-base/6">
54	        {CTA_PRIMARY.stickyBarText}
55	      </p>
56	      <a
57	        href={primaryHref}
58	        class="inline-flex h-10 shrink-0 items-center justify-center rounded-md bg-orange-600 px-5 text-sm font-semibold whitespace-nowrap text-white transition-colors hover:bg-orange-700 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-blue-800 focus:outline-none"
59	        data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
60	        data-ph-capture-attribute-cta-surface="sticky-bar"
61	        data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
62	      >
63	        {CTA_PRIMARY.stickyBarButtonText}
64	      </a>
65	    </div>
66	
67	    {/* Test variant: rendered only when CTA_VARIANT is populated in cta.ts */}
68	    {
69	      CTA_VARIANT && (
70	        <div
71	          class="hidden flex-col items-center gap-2 text-center sm:flex-row sm:gap-6"
72	          data-variant="variant"
73	        >
74	          <p class="text-sm/5 font-medium sm:text-base/6">
75	            {CTA_VARIANT.stickyBarText}
76	          </p>
77	          <a
78	            href={variantHref}
79	            class="inline-flex h-10 shrink-0 items-center justify-center rounded-md bg-orange-600 px-5 text-sm font-semibold whitespace-nowrap text-white transition-colors hover:bg-orange-700 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-blue-800 focus:outline-none"
80	            data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
81	            data-ph-capture-attribute-cta-surface="sticky-bar"
82	            data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.variant}
83	          >
84	            {CTA_VARIANT.stickyBarButtonText}
85	          </a>
86	        </div>
87	      )
88	    }
89	  </div>
90	
91	  <button
92	    type="button"
93	    class="absolute top-1/2 right-2 flex size-9 -translate-y-1/2 items-center justify-center rounded-md text-2xl/none text-blue-100 transition-colors hover:bg-blue-700 hover:text-white focus:ring-2 focus:ring-white focus:outline-none"
94	    data-cta-dismiss
95	    aria-label={STICKY_BAR_CONFIG.dismissLabel}
96	  >
97	    <span aria-hidden="true">&times;</span>
98	  </button>
99	</div>
100	
101	<script>
102	  import { AB_TEST_ENABLED, type Attribution } from '@/constants/cta';
103	  import {
104	    isStickyBarDismissed,
105	    recordStickyBarDismissed,
106	  } from '@/utils/storage';
107	  import { captureCtaEvent } from '@/utils/cta-analytics';
108	
109	  const bar = document.querySelector<HTMLElement>('[data-cta-sticky-bar]');
110	
111	  if (bar) {
112	    const attribution = (bar.dataset.attribution ?? 'page') as Attribution;
113	
114	    // Pick random variant (or always primary if A/B testing disabled)
115	    const variantId =
116	      AB_TEST_ENABLED && Math.random() >= 0.5 ? 'variant' : 'primary';
117	    const variantEl = bar.querySelector(`[data-variant="${variantId}"]`);
118	    if (variantEl) {
119	      variantEl.classList.remove('hidden');
120	      variantEl.classList.add('flex');
121	    }
122	
123	    // Already dismissed this session: leave it hidden and record nothing. An
124	    // impression the visitor never saw would inflate the denominator of every
125	    // rate computed from cta_shown.
126	    if (!isStickyBarDismissed()) {
127	      bar.classList.remove('hidden');
128	      captureCtaEvent('cta_shown', 'sticky-bar', attribution);
129	    }
130	
131	    bar.querySelector('[data-cta-dismiss]')?.addEventListener('click', () => {
132	      bar.classList.add('hidden');
133	      recordStickyBarDismissed();
134	      captureCtaEvent('cta_dismissed', 'sticky-bar', attribution);
135	    });
136	  }
137	</script>
