1	/**
2	 * Browser storage for CTA surface suppression.
3	 *
4	 * The two pinned surfaces suppress on different clocks and in different stores,
5	 * because they are asking for different amounts of patience:
6	 *
7	 * - Slide-in: 15 days in localStorage, timed from when it APPEARED. Dismissing
8	 *   it early changes nothing; the clock has already started.
9	 * - Sticky bar: the rest of the session, in sessionStorage, timed from
10	 *   DISMISSAL. It shows on nearly every page, so a fortnight-long silence would
11	 *   be too much, and sessionStorage means "session" needs no date arithmetic.
12	 *
13	 * Every read fails open: if storage is unavailable (SSR, private browsing, a
14	 * locked-down browser) the surface shows. Showing a CTA one time too many is a
15	 * smaller harm than a surface that silently never appears for a slice of
16	 * visitors nobody can identify.
17	 */
18	
19	const SLIDE_IN_LAST_SHOWN_KEY = 'agilePainRelief:ctaSlideInLastShown';
20	const STICKY_BAR_DISMISSED_KEY = 'agilePainRelief:ctaStickyBarDismissed';
21	
22	/**
23	 * Check if localStorage is available in the current environment
24	 * Handles SSR, private browsing modes, and disabled storage
25	 *
26	 * @returns {boolean} True if localStorage is available and writable
27	 */
28	export function isLocalStorageAvailable(): boolean {
29	  try {
30	    const testKey = '__storage_test__';
31	    localStorage.setItem(testKey, 'test');
32	    localStorage.removeItem(testKey);
33	    return true;
34	  } catch (e) {
35	    console.warn('localStorage is not available:', e);
36	    return false;
37	  }
38	}
39	
40	/**
41	 * Check if sessionStorage is available in the current environment
42	 *
43	 * @returns {boolean} True if sessionStorage is available and writable
44	 */
45	export function isSessionStorageAvailable(): boolean {
46	  try {
47	    const testKey = '__storage_test__';
48	    sessionStorage.setItem(testKey, 'test');
49	    sessionStorage.removeItem(testKey);
50	    return true;
51	  } catch (e) {
52	    console.warn('sessionStorage is not available:', e);
53	    return false;
54	  }
55	}
56	
57	/**
58	 * Check whether the slide-in's suppression window has lapsed.
59	 *
60	 * @param {number} intervalDays - Days between slide-in appearances
61	 * @returns {boolean} True if the slide-in may be shown
62	 *
63	 * @example
64	 * if (shouldShowSlideIn(15)) {
65	 *   // Arm the scroll trigger
66	 * }
67	 */
68	export function shouldShowSlideIn(intervalDays: number): boolean {
69	  try {
70	    if (!isLocalStorageAvailable()) {
71	      return true;
72	    }
73	
74	    const lastShownStr = localStorage.getItem(SLIDE_IN_LAST_SHOWN_KEY);
75	
76	    // Never shown before
77	    if (!lastShownStr) {
78	      return true;
79	    }
80	
81	    const lastShown = parseInt(lastShownStr, 10);
82	
83	    // Corrupted data
84	    if (isNaN(lastShown)) {
85	      console.warn('Invalid timestamp in localStorage, showing slide-in');
86	      return true;
87	    }
88	
89	    const intervalMs = intervalDays * 24 * 60 * 60 * 1000;
90	    return Date.now() - lastShown >= intervalMs;
91	  } catch (e) {
92	    console.warn('Error checking slide-in frequency, defaulting to show:', e);
93	    return true;
94	  }
95	}
96	
97	/**
98	 * Start the slide-in's suppression window. Called when it appears, not when it
99	 * is dismissed.
100	 *
101	 * @returns {boolean} True if successfully recorded, false otherwise
102	 */
103	export function recordSlideInShown(): boolean {
104	  try {
105	    if (!isLocalStorageAvailable()) {
106	      return false;
107	    }
108	
109	    localStorage.setItem(SLIDE_IN_LAST_SHOWN_KEY, Date.now().toString());
110	    return true;
111	  } catch (e) {
112	    console.warn('Failed to record slide-in shown timestamp:', e);
113	    return false;
114	  }
115	}
116	
117	/**
118	 * Whether the visitor has dismissed the sticky bar during this session.
119	 *
120	 * @returns {boolean} True if it was dismissed and should stay hidden
121	 */
122	export function isStickyBarDismissed(): boolean {
123	  try {
124	    if (!isSessionStorageAvailable()) {
125	      return false;
126	    }
127	
128	    return sessionStorage.getItem(STICKY_BAR_DISMISSED_KEY) !== null;
129	  } catch (e) {
130	    console.warn('Error checking sticky bar dismissal, defaulting to show:', e);
131	    return false;
132	  }
133	}
134	
135	/**
136	 * Suppress the sticky bar for the rest of this session.
137	 *
138	 * @returns {boolean} True if successfully recorded, false otherwise
139	 */
140	export function recordStickyBarDismissed(): boolean {
141	  try {
142	    if (!isSessionStorageAvailable()) {
143	      return false;
144	    }
145	
146	    sessionStorage.setItem(STICKY_BAR_DISMISSED_KEY, 'true');
147	    return true;
148	  } catch (e) {
149	    console.warn('Failed to record sticky bar dismissal:', e);
150	    return false;
151	  }
152	}
153	
154	/**
155	 * Clear both surfaces' suppression state. Useful when testing by hand.
156	 */
157	export function clearCtaSuppression(): void {
158	  try {
159	    if (isLocalStorageAvailable()) {
160	      localStorage.removeItem(SLIDE_IN_LAST_SHOWN_KEY);
161	    }
162	    if (isSessionStorageAvailable()) {
163	      sessionStorage.removeItem(STICKY_BAR_DISMISSED_KEY);
164	    }
165	  } catch (e) {
166	    console.warn('Failed to clear CTA suppression state:', e);
167	  }
168	}
